<?php
namespace App\Services\DevOps;use App\Models\ZigoDeployment;
final class DeploymentTimelineViewModel {private const STEPS=['upload','validate','start','php-l','backup','copy','migrate','seed','optimize-clear','config-cache','route-cache','view-cache','health','finish','rollback'];public function build(ZigoDeployment $deployment):array{$logs=$deployment->logs()->oldest('created_at')->get();$result=[];foreach(self::STEPS as $step){$matching=$logs->filter(fn($l)=>$l->step===$step||($step==='seed'&&$l->step==='seeder'));$first=$matching->first();$last=$matching->last();$result[]=['step'=>$step,'time'=>$first?->created_at,'duration_ms'=>$first&&$last?(int)$first->created_at->diffInMilliseconds($last->created_at):null,'level'=>$last?->level??'pending','result'=>$last?($last->level==='error'?'failed':'completed'):'pending','message'=>$last?->message??'Sin evidencia registrada.'];}return$result;}}
